### 💻 Final Code (simple, easy-to-understand version)

```cpp
#include <iostream>
using namespace std;

class Complex {
    int real, imag;

public:
    // Constructor
    Complex(int r = 0, int i = 0) {
        real = r;
        imag = i;
    }

    // Display function
    void show() {
        cout << real << " + " << imag << "i" << endl;
    }

    // PREFIX ++ (e.g. ++c1)
    Complex operator++() {
        ++real;
        ++imag;
        return *this; // return updated object
    }

    // POSTFIX ++ (e.g. c1++)
    Complex operator++(int) {
        Complex temp = *this; // keep old value
        real++;
        imag++;
        return temp; // return old object
    }

    // BINARY + (add two complex numbers)
    Complex operator+(Complex c2) {
        Complex temp;
        temp.real = real + c2.real;
        temp.imag = imag + c2.imag;
        return temp;
    }

    // BINARY < (compare two complex numbers)
    bool operator<(Complex c2) {
        int mag1 = real * real + imag * imag;
        int mag2 = c2.real * c2.real + c2.imag * c2.imag;
        return mag1 < mag2;
    }
};

int main() {
    Complex c1(3, 4), c2(2, 5), c3;
    int choice;

    do {
        cout << "\n=== MENU ===\n";
        cout << "1. Prefix Increment (++c1)\n";
        cout << "2. Postfix Increment (c1++)\n";
        cout << "3. Add Two Complex Numbers (c1 + c2)\n";
        cout << "4. Compare Two Complex Numbers (c1 < c2)\n";
        cout << "5. Exit\n";
        cout << "Enter your choice: ";
        cin >> choice;

        switch (choice) {
            case 1:
                ++c1;
                cout << "After prefix increment: ";
                c1.show();
                break;

            case 2:
                c1++;
                cout << "After postfix increment: ";
                c1.show();
                break;

            case 3:
                c3 = c1 + c2;
                cout << "Sum: ";
                c3.show();
                break;

            case 4:
                if (c1 < c2)
                    cout << "c1 is smaller than c2" << endl;
                else
                    cout << "c1 is not smaller than c2" << endl;
                break;

            case 5:
                cout << "Exiting..." << endl;
                break;

            default:
                cout << "Invalid choice!" << endl;
        }

    } while (choice != 5);

    return 0;
}
```

